#!/usr/bin/env bash
# Generated by Codex for the Part 3 barrier experiment.
# Run on an LS6 A100 node: bash barrier_experiment.sh
# Only the temporary copy of kernels.cu is modified.
set -euo pipefail

cd "$(dirname "$0")"
source_dir=$PWD
output_dir="$source_dir/../results/barriers/$(date +%Y%m%d-%H%M%S)"
mkdir -p "$output_dir"
work_dir=$(mktemp -d)
trap 'rm -rf "$work_dir"' EXIT

cp kernels.cu kernels.cuh parts.h sgemm.cu Makefile "$work_dir/"
cd "$work_dir"

{
    hostname
    nvidia-smi
    nvcc --version
} > "$output_dir/environment.txt" 2>&1

# Incorrect variants may fail check; record their exit status and continue.
record_experiment() {
    local name=$1
    shift
    local status=0
    "$@" > "$output_dir/$name.txt" 2>&1 || status=$?
    printf '%s exit status: %s\n' "$name" "$status" | tee -a "$output_dir/status.txt"
}

for barrier in first second; do
    # Start each experiment from the original, never from the other variant.
    python3 - "$source_dir/kernels.cu" "$barrier" <<'PY'
from pathlib import Path
import sys

source = Path(sys.argv[1]).read_text()
start = source.index("template <int T>\n__global__ void sgemm_tiled_kernel")
end = source.index("// PROVIDED: launch the kernel", start)
body = source[start:end]
barrier = "__syncthreads();"
assert body.count(barrier) == 2, "Expected exactly two tiled barriers"
position = body.index(barrier) if sys.argv[2] == "first" else body.rindex(barrier)
body = body[:position] + "// Barrier removed for this experiment." + body[position + len(barrier):]
Path("kernels.cu").write_text(source[:start] + body + source[end:])
PY
    make -B > "$output_dir/${barrier}_build.txt" 2>&1
    record_experiment "${barrier}_check" ./sgemm check
    record_experiment "${barrier}_racecheck" \
        compute-sanitizer --tool racecheck ./sgemm tiled 256 --once
done

# Rebuild the unmodified source and require both final checks to pass.
cp "$source_dir/kernels.cu" kernels.cu
make -B > "$output_dir/restored_build.txt" 2>&1
make check > "$output_dir/restored_check.txt" 2>&1
make sanitize > "$output_dir/restored_sanitize.txt" 2>&1
printf 'Original kernel passed check and sanitize.\n' | tee -a "$output_dir/status.txt"
printf 'Results saved in %s\n' "$output_dir"
